float:
(x[768]) {
  indexing: input title | embed embedder_base | attribute | index
  attribute {
    distance-metric: prenormalized-angular
  }
  index {
    hnsw {
      max-links-per-node: 16
      neighbors-to-explore-at-insert: 200
    }
  }
}


rank-profile semantic_base {
    # 768, not 384 - bge-base's width. Everything else here mirrors
    # `semantic.profile`: the query vector still arrives as an input rather
    # than being computed per document.
    inputs {
        query(qb) tensor(x[768])
    }
    first-phase {
        expression: closeness(field, title_embedding_base)
    }
    match-features {
        closeness(field, title_embedding_base)
        distance(field, title_embedding_base)
    }
}
